// Evaluate all health checks
const chatwoot = $node['Check Chatwoot'].json?.status === 'ok' ? 'healthy' : 'unhealthy';
const n8n = $node['Check n8n'].json?.data ? 'healthy' : 'unhealthy';
const jambonz = $node['Check Jambonz'].json?.status === 'ok' ? 'healthy' : 'unhealthy';
const daanaaAPI = $node['Check Daanaa API'].json?.status === 200 ? 'healthy' : 'unhealthy';
const backlogCount = $node['Get Chatwoot Backlog Count'].json?.payload?.length || 0;

const alerts = [];

// Check service health
if (chatwoot === 'unhealthy') {
  alerts.push({ severity: 'critical', message: 'Chatwoot is down', action: 'docker-compose -f /opt/chatwoot/docker-compose.yml restart' });
}
if (n8n === 'unhealthy') {
  alerts.push({ severity: 'critical', message: 'n8n is down', action: 'docker-compose -f /opt/n8n/docker-compose.yml restart' });
}
if (jambonz === 'unhealthy') {
  alerts.push({ severity: 'critical', message: 'Jambonz is down', action: 'docker-compose -f /opt/jambonz/docker-compose.yml restart' });
}
if (daanaaAPI === 'unhealthy') {
  alerts.push({ severity: 'warning', message: 'Daanaa API unresponsive', action: 'Check API logs: tail -f /var/log/daanaa_api.log' });
}

// Check backlog
if (backlogCount > 15) {
  alerts.push({ severity: 'warning', message: 'High backlog: ' + backlogCount + ' unresolved tickets', action: 'Review and prioritize oldest escalations' });
}

return {
  timestamp: new Date().toISOString(),
  services: {
    chatwoot,
    n8n,
    jambonz,
    daanaa_api: daanaaAPI
  },
  metrics: {
    backlog_count: backlogCount
  },
  alerts: alerts,
  alert_count: alerts.length,
  healthy: alerts.length === 0
};
